const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/** Thrown for any malformed input; `line` is null for whole-input errors. */
export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
