        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 2) {
        throw new ParseError('expected candidates <name>...', lineNo)
      }
      const names = tokens.slice(1)
      const set = new Set()
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNo)
        }
        if (set.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNo)
        }
        set.add(name)
      }
      candidateSet = set
      candidateOrder = names
    } else if (word === 'ballot') {
      if (candidateSet === null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      sawBallot = true
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNo)
      }
      if (!COUNT_PATTERN.test(tokens[1])) {
        throw new ParseError('count must be a positive integer', lineNo)
      }
      const count = Number(tokens[1])
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`unknown directive ${word}`, lineNo)
    }
  }

  if (candidateSet === null) {
    throw new ParseError('no candidates', null)
  }

  return { candidates: candidateOrder, ballots }
}
"}

