{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-uPf3O8/src/count.js","content":"/**
 * The instant-runoff count itself: rounds of tallying, majority detection,
 * and elimination of the weakest candidate (with round-by-round tie
 * breaking), per the task specification.
 */

/**
 * Counts `ballots` over `candidates` and returns the list of rounds counted.
 * Each round is `{ counts, exhausted, eliminated, winner, noWinner }`, where
 * `counts` is a Map from every candidate continuing that round to their
 * vote total, `eliminated` is the name removed after that round (or null),
 * and exactly one of `winner` (a name) or `noWinner` (true) holds on the
 * final round.
 */
export function countRounds(candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []
  const history = []

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0)

    let exhausted = 0
    for (const ballot of ballots) {
      const pick = ballot.names.find((name) => continuing.has(name))
      if (pick === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(pick, counts.get(pick) + ballot.count)
      }
    }

    history.push(counts)
    const activeTotal = sum(counts.values())
    const round = { counts, exhausted, eliminated: null, winner: null, noWinner: false }
    rounds.push(round)

    if (activeTotal === 0) {
      round.noWinner = true
      return rounds
    }

    const winner = [...counts.entries()].find(([, votes]) => votes * 2 > activeTotal)
    if (winner) {
      round.winner = winner[0]
      return rounds
    }

    const fewest = Math.min(...counts.values())
    const tied = [...counts.keys()].filter((name) => counts.get(name) === fewest)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }
}

function sum(values) {
  let total = 0
  for (const value of values) total += value
  return total
}

/**
 * Narrows `tied` (candidates tied for fewest votes this round) by comparing
 * their counts round by round from the first round onward, keeping only
 * those with the fewest at the first round where they differ. When no round
 * separates them, the one whose name sorts last by code point is chosen.
 */
function breakTie(tied, history) {
  let candidates = tied
  for (const roundCounts of history) {
    if (candidates.length === 1) break
    const votes = candidates.map((name) => roundCounts.get(name))
    if (votes.some((v) => v === undefined)) continue
    if (votes.every((v) => v === votes[0])) continue
    const min = Math.min(...votes)
    candidates = candidates.filter((name) => roundCounts.get(name) === min)
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.reduce((last, name) => (name > last ? name : last))
}
"}

