/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { countRounds } from './count.js'
import { formatRoundLine } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
  fail('usage: cli.js rounds|tally')
}

const input = readFileSync(0, 'utf8')

let election
try {
  election = parseElection(input)
} catch (err) {
  if (!(err instanceof ParseError)) throw err
  const location = err.line === null ? '' : `line ${err.line}: `
  fail(`${location}${err.message}`)
}

const rounds = countRounds(election.candidates, election.ballots)
const lines = []

if (mode === 'rounds') {
  for (const [index, round] of rounds.entries()) {
    lines.push(formatRoundLine(index + 1, round.counts, round.exhausted))
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  }
} else {
  lines.push(`rounds ${rounds.length}`)
}

const finalRound = rounds[rounds.length - 1]
lines.push(finalRound.winner !== null ? `winner ${finalRound.winner}` : 'no winner')

process.stdout.write(lines.join('\n') + '\n')
"}

